328 |      * @notice See {ILegionBaseSale-supplyTokens}.
329 |      */
330 |     function supplyTokens(uint256 amount, uint256 legionFee) external virtual onlyProject askTokenAvailable {
331 |         /// Verify that tokens can be supplied for distribution
332 |         _verifyCanSupplyTokens(amount);
333 | 
334 |         /// Verify that the sale is not canceled
335 |         _verifySaleNotCanceled();
336 | 
337 |         /// Verify that tokens have not been supplied
338 |         _verifyTokensNotSupplied();
339 | 
340 |         /// Flag that tokens have been supplied
341 |         tokensSupplied = true;
342 | 
343 |         /// Calculate and verify Legion Fee
344 |         if (legionFee != (legionFeeOnTokensSoldBps * amount) / 10000) revert InvalidFeeAmount();
345 | 
346 |         /// Emit successfully TokensSuppliedForDistribution
347 |         emit TokensSuppliedForDistribution(amount, legionFee);
348 | 
349 |         /// Transfer the allocated amount of tokens for distribution
350 |         IERC20(askToken).safeTransferFrom(msg.sender, address(this), amount);
351 | 
352 |         /// Transfer the Legion fee to the Legion fee receiver address
353 |         if (legionFee != 0) IERC20(askToken).safeTransferFrom(msg.sender, legionFeeReceiver, legionFee);
354 |     }
