369 |         /// Set the merkle root for claiming excess capital
370 |         excessCapitalMerkleRoot = merkleRoot;
371 | 
372 |         /// Emit successfully ExcessCapitalResultsPublished
373 |         emit ExcessCapitalResultsPublished(merkleRoot);
374 |     }
